from math import comb
def binom_pmf(k,n,p):
    return comb(n,k)*p**k*(1-p)**(n-k)
print(round(binom_pmf(3,10,0.3),4))  # 0.2668

from math import exp, factorial
def poisson_pmf(k, lam):
    return exp(-lam)*lam**k/factorial(k)
print(round(poisson_pmf(2, 3.0), 4))  # 0.2240

import math
def Phi(z):
    return 0.5*(1+math.erf(z/math.sqrt(2)))
print(round(Phi(1.96),4))  # 0.9750

import math
def neg_loglik_bernoulli(p, k, n):
    return -(k*math.log(p) + (n-k)*math.log(1-p))
# minimized at p = k/n; check numerically
print(round(30/100, 3))  # 0.3

import math
def sigmoid(z):
    return 1/(1+math.exp(-z))
# log-odds 0.4 -> probability
print(round(sigmoid(0.4),4))  # 0.5987

import math, random
def target(x):            # unnormalized: standard normal
    return math.exp(-x*x/2)
x = 0.0; samples = []
for _ in range(50000):
    xp = x + random.uniform(-1,1)
    if random.random() < min(1, target(xp)/target(x)):
        x = xp
    samples.append(x)
print(round(sum(samples)/len(samples),3))  # near 0

import math
def entropy(ps):
    return -sum(p*math.log2(p) for p in ps if p > 0)
print(round(entropy([0.5,0.5]),3))    # 1.0 bit
print(round(entropy([0.9,0.1]),3))    # 0.469 bits

import math
def kl(p, q):
    return sum(pi*math.log2(pi/qi) for pi,qi in zip(p,q) if pi>0)
print(round(kl([0.5,0.5],[0.9,0.1]),4))  # 0.7370 bits
